code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Zero regions reachable from the edge are outside; other zero cells are holes.
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc)); q.append((nr, nc))
    inside = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0 and (r, c) not in outside}

    # For every 4-connected 1-component enclosing a hole, add a 3 inner rim
    # and a 2 outer halo around the whole component.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                cr, cc = q.popleft()
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and (nr, nc) not in seen:
                        seen.add((nr, nc)); comp.add((nr, nc)); q.append((nr, nc))
            has_hole = any((cr + dr, cc + dc) in inside
                           for cr, cc in comp for dr, dc in dirs
                           if 0 <= cr + dr < h and 0 <= cc + dc < w)
            if not has_hole:
                continue
            for cr, cc in comp:
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                        if (nr, nc) in inside:
                            out[nr][nc] = 3
                        elif out[nr][nc] != 3:
                            out[nr][nc] = 2
    return out
'''
